using Microsoft.EntityFrameworkCore;
using PeopleHub.Infrastructure.Persistence;
using PeopleHub.Application.Common;
using PeopleHub.Application.Modules.Attendance;
using PeopleHub.Application.Modules.Platform;
using PeopleHub.Domain.Entities;
namespace PeopleHub.Tests;
public class AttendanceExceptionTests
{
 class User(int employee=6,bool hr=false):ICurrentUser{public string Email=>"exception@example.local";public int? EmployeeId=>employee;public int UserId=>1;public bool IsAuthenticated=>true;public bool IsInRole(string r)=>hr;public bool Can(string p)=>hr;}
 class Fixed:TimeProvider{public override DateTimeOffset GetUtcNow()=>new(2026,11,24,17,0,0,TimeSpan.Zero);}
 static async Task<AppDbContext> Db(){var d=new AppDbContext(new DbContextOptionsBuilder<AppDbContext>().UseSqlite("Data Source=:memory:").Options);await d.Database.OpenConnectionAsync();await d.Database.MigrateAsync();await SeedData.InitializeAsync(d,"Admin123!","Demo123!",new DateTime(2026,11,24));return d;}
 static AttendanceExceptions S(AppDbContext d,User? u=null){u??=new();return new(d,u,new AccessScope(d,u),new AppClock(new Fixed()));}
 [Fact]public async Task ExceptionsShowMissingEndsOnlyAfterShiftEndAndRespectScope(){await using var d=await Db();var day=new DateTime(2026,10,2);d.Add(new AttendanceRecord{EmployeeId=6,Date=day,CheckIn=day.AddHours(9)});d.Add(new AttendanceRecord{EmployeeId=7,Date=day,CheckOut=day.AddHours(17)});d.Add(new AttendancePeriodLock{EmployeeId=6,Year=2026,Month=10});await d.SaveAsync();var own=await S(d).GetAsync(day,day);var one=Assert.Single(own.Rows);Assert.Equal("MissingOut",one.Kind);Assert.True(one.Locked);Assert.Single((await S(d,new(7)).GetAsync(day,day)).Rows);Assert.Equal("MissingIn",(await S(d,new(7)).GetAsync(day,day)).Rows.Single().Kind);}
 [Fact]public async Task NightShiftDoesNotFlagUntilFollowingMorning(){await using var d=await Db();var e=(await d.Set<Employee>().FindAsync(6))!;var shift=new Shift{Name="Night",Start=new(22,0,0),End=new(6,0,0)};d.Add(shift);await d.SaveAsync();e.ShiftId=shift.Id;var day=new DateTime(2026,11,24);var rec=await d.Set<AttendanceRecord>().FirstOrDefaultAsync(x=>x.EmployeeId==6&&x.Date==day);if(rec==null){rec=new(){EmployeeId=6,Date=day};d.Add(rec);}rec.CheckIn=day.AddHours(22);rec.CheckOut=null;await d.SaveAsync();Assert.Empty((await S(d).GetAsync(day,day)).Rows);}
 [Fact]public async Task UnmatchedRawPunchesAreOnlyVisibleToAttendanceManagers(){await using var d=await Db();var day=new DateTime(2026,11,23);d.Add(new DevicePunch{DeviceUserId="unknown",Time=day.AddHours(9)});await d.SaveAsync();Assert.Empty((await S(d).GetAsync(day,day)).Unmatched);Assert.Single((await S(d,new(1,true)).GetAsync(day,day)).Unmatched);await Assert.ThrowsAsync<DomainException>(()=>S(d).GetAsync(day.AddDays(-100),day));}
 [Fact]public async Task ReprocessingIsPermissionedIdempotentAndPreservesLockedManualAndExcused(){await using var d=await Db();var day=new DateTime(2026,10,2);var u=new User(1,true);var c=new AppClock(new Fixed());var svc=new DeviceService(d,c,new AuditService(d,u,c),u);await Assert.ThrowsAsync<DomainException>(()=>new DeviceService(d,c,new AuditService(d,new User(),c),new User()).ReprocessAsync());d.Add(new AttendanceRecord{EmployeeId=6,Date=day,CheckIn=day.AddHours(8),CheckOut=day.AddHours(16),Source=AttendanceSource.Manual});d.Add(new AttendanceRecord{EmployeeId=7,Date=day,IsExcused=true,Source=AttendanceSource.Manual});await d.SaveAsync();await svc.IngestAsync([new("PH-006",day.AddHours(10)),new("PH-007",day.AddHours(10)),new("PH-008",day.AddHours(9)),new("PH-008",day.AddHours(17))]);var count=await d.Set<AttendanceEvidence>().CountAsync();await svc.ReprocessAsync();Assert.Equal(count,await d.Set<AttendanceEvidence>().CountAsync());Assert.Equal(day.AddHours(8),(await d.Set<AttendanceRecord>().SingleAsync(x=>x.EmployeeId==6&&x.Date==day)).CheckIn);Assert.True((await d.Set<AttendanceRecord>().SingleAsync(x=>x.EmployeeId==7&&x.Date==day)).IsExcused);Assert.Equal(4,await d.Set<DevicePunch>().CountAsync());}
}
